INSERT INTO feature VALUES('signatures-as-values','descriptions','Signatures as values (sign, Sig)',NULL,'implemented','notable',NULL,'A `theory` block presents sorts, operations and rules as a value of the data type `Theory` (renamed from `sign`/`Sig` by #741). A source''s own constructor named like one of `Theory`''s keeps its name beside the block, whichever is declared first. A theory a source imports is a value too, `Gandr.Package` from `std.build`, the members of each theory it includes flattened before its own, and a source with no `theory` block of its own reads its links by their qualified names, `Theory.Const`. `Model(T)` reads a theory''s name, so a `Theory` variable names no model type. `std.build`''s `modelType` computes from a presentation''s value the type of its models'' entries instead, one entry for each constant at `String` or `Bool`, as nested pairs, and an equivalence relates `Model(T)` to it, checked for `Gandr.Package` and for a local theory; `encode` folds such a model''s entries by its theory''s value.','surface-lowering theory-levitation','corpus/model/desc/generic-arity.gandr corpus/model/desc/desc-inspect.gandr corpus/model/desc/generic-arity-behind.gandr corpus/model/desc/theory-constructor-names.gandr corpus/model/desc/module-reflection.gandr corpus/pathological/desc/module-reflection.gandr','corpus/ledger/features/signatures-as-values.gandr',NULL);
